const mail = $('Email Trigger (IMAP)').first();
const text = ($input.first().json.text || '').trim();

const prompt = `Extrais les données de cette facture. Réponds uniquement en JSON avec ces clés :
supplier_name, invoice_number, invoice_date (YYYY-MM-DD), due_date (YYYY-MM-DD ou null), currency (code à 3 lettres),
subtotal, tax_amount, total_amount (nombres), items (liste de {description, quantity, unit_price, line_total}).
Si une valeur est absente, mets null. N'invente rien.

FACTURE :
${text}`;

return [{
  json: {
    from: mail.json.from?.text || mail.json.from || '',
    subject: mail.json.subject || '',
    fileName: mail.binary.attachment_0.fileName,
    ocrText: text,
    textLength: text.length,
    body: {
      contents: [{ parts: [{ text: prompt }] }],
      generationConfig: { responseMimeType: "application/json", temperature: 0 }
    }
  }
}];

const prep = $('Prepare Gemini').first().json;
const parts = $input.first().json.candidates?.[0]?.content?.parts || [];
const raw = parts.map(p => p.text || '').join('').replace(/```json|```/g, '').trim();

const errors = [];
let data = {};
try { data = JSON.parse(raw); } catch (e) { errors.push('JSON invalide renvoyé par le LLM'); }

const num = v => (v === null || v === undefined || v === '') ? null : Number(v);
const items = Array.isArray(data.items) ? data.items : [];
const itemsSum = items.reduce((s, i) => s + (num(i.line_total) || 0), 0);
const subtotal = num(data.subtotal);
const tax = num(data.tax_amount) ?? 0;
const total = num(data.total_amount);

// Champs obligatoires
if (!data.supplier_name) errors.push('supplier_name manquant');
if (!data.invoice_number) errors.push('invoice_number manquant');
if (total === null || isNaN(total)) errors.push('total_amount manquant');

// Date
const dateOk = /^\d{4}-\d{2}-\d{2}$/.test(data.invoice_date || '') && !isNaN(Date.parse(data.invoice_date));
if (!dateOk) errors.push('invoice_date invalide (attendu YYYY-MM-DD)');

// Devise
if (!/^[A-Z]{3}$/.test(data.currency || '')) errors.push('currency invalide');

// Cohérence des montants
if (items.length === 0) errors.push('aucune ligne de facture');
if (total !== null && items.length && Math.abs(itemsSum + tax - total) > 0.01)
  errors.push(`total incohérent : lignes ${itemsSum} + taxe ${tax} ≠ ${total}`);
items.forEach((i, n) => {
  const q = num(i.quantity), u = num(i.unit_price), l = num(i.line_total);
  if (q !== null && u !== null && l !== null && Math.abs(q * u - l) > 0.01)
    errors.push(`ligne ${n + 1} : quantité × prix unitaire ≠ total ligne`);
});

return [{
  json: {
    status: errors.length ? 'needs_review' : 'validated',
    errors,
    file_name: prep.fileName,
    source_email: prep.from,
    extracted_text: prep.ocrText,
    supplier_name: data.supplier_name || null,
    invoice_number: data.invoice_number || null,
    invoice_date: dateOk ? data.invoice_date : null,
    currency: data.currency || null,
    subtotal,
    tax_amount: num(data.tax_amount),
    total_amount: total,
    extraction_data: data
  }
}];

const inv = $('Parse & Validate').first().json;
const save = $input.first().json;
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmt = n => n === null || n === undefined ? '-' : Number(n).toLocaleString('fr-FR');

let kind, subject, banner;
if (!save.inserted) {
  kind = 'duplicate';
  subject = `[DocuFlow] Doublon ignoré : ${inv.invoice_number}`;
  banner = `Cette facture existe déjà (document n° ${save.existing_document_id}). Aucune insertion.`;
} else if (inv.status === 'needs_review') {
  kind = 'needs_review';
  subject = `[DocuFlow] À vérifier : ${inv.invoice_number}`;
  banner = 'Facture enregistrée avec des anomalies : ' + inv.errors.join(' ; ');
} else {
  kind = 'success';
  subject = `[DocuFlow] Facture traitée : ${inv.invoice_number}`;
  banner = `Facture enregistrée avec succès (document n° ${save.document_id}).`;
}

const items = inv.extraction_data?.items || [];
const rows = items.map(i =>
  `<tr><td>${esc(i.description)}</td><td align="right">${fmt(i.quantity)}</td><td align="right">${fmt(i.unit_price)}</td><td align="right">${fmt(i.line_total)}</td></tr>`
).join('');

const html = `
<div style="font-family:Arial,sans-serif;max-width:640px">
  <h2>DocuFlow AI : rapport de traitement</h2>
  <p style="padding:10px;background:#f2f2f2;border-left:4px solid ${kind === 'success' ? '#2e9e5b' : '#d9822b'}">${esc(banner)}</p>
  <table cellpadding="6" style="border-collapse:collapse">
    <tr><td><b>Fichier</b></td><td>${esc(inv.file_name)}</td></tr>
    <tr><td><b>Fournisseur</b></td><td>${esc(inv.supplier_name)}</td></tr>
    <tr><td><b>N° facture</b></td><td>${esc(inv.invoice_number)}</td></tr>
    <tr><td><b>Date</b></td><td>${esc(inv.invoice_date)}</td></tr>
    <tr><td><b>Total</b></td><td>${fmt(inv.total_amount)} ${esc(inv.currency)}</td></tr>
    <tr><td><b>Expéditeur</b></td><td>${esc(inv.source_email)}</td></tr>
  </table>
  <h3>Lignes</h3>
  <table border="1" cellpadding="6" style="border-collapse:collapse;width:100%">
    <tr><th>Désignation</th><th>Qté</th><th>Prix unitaire</th><th>Total</th></tr>${rows}
  </table>
</div>`;

return [{ json: { kind, subject, html } }];
